// Get input data - headers are inside json!
const data = $input.item.json;
const body = data.body || data;
const headers = data.headers || {};

// Your TwitterAPI.io API key
const EXPECTED_API_KEY: "YOUR_API_KEY";

console.log('📋 Checking API key...');

// Get API key from headers
const receivedApiKey = headers['x-api-key'];

if (!receivedApiKey) {
  console.log('❌ No API key found in headers');
  throw new Error('No API key found in request');
}

if (receivedApiKey !== EXPECTED_API_KEY) {
  console.log(`❌ Invalid API key: got "${receivedApiKey}"`);
  throw new Error('Invalid API key');
}

console.log('✅ Valid webhook request from TwitterAPI.io');
console.log(`📥 Event: ${body.eventtype || body.event_type}`);
console.log(`📥 Rule: ${body.ruletag || body.rule_tag}`);
console.log(`📥 Tweets: ${body.tweets?.length || 0}`);

// Pass through the BODY only (not the headers wrapper)
return [{
  json: body
}];

const body = $input.item.json;

// Check event type
if (body.eventtype !== 'tweet' && body.event_type !== 'tweet') {
  console.log('⚠️ Non-tweet event, skipping');
  return [];
}

const tweets = body.tweets || [];
const ruleTag = body.ruletag || body.rule_tag || 'unknown';

console.log(`📥 Processing ${tweets.length} tweets from rule "${ruleTag}"`);

if (tweets.length === 0) {
  console.log('No tweets in webhook payload');
  return [];
}

// Normalize each tweet to match your existing workflow format
return tweets.map(tweet => ({
  json: {
    // Keep all original TwitterAPI.io fields
    ...tweet,

    // Normalize date field (ensure consistency)
    createdAt: tweet.created_at || tweet.createdAt,

    // Normalize reply fields
    isReply: tweet.is_reply || tweet.isReply || !!tweet.inReplyToId || !!tweet.in_reply_to_status_id,
    inReplyToId: tweet.inReplyToId || tweet.in_reply_to_status_id || null,
    inReplyToUsername: tweet.inReplyToUsername || tweet.in_reply_to_screen_name || null,

    // Add webhook metadata
    webhook_source: ruleTag,
    webhook_timestamp: body.timestamp
  }
}));

const tweets = $input.all();
const apiKey: "YOUR_API_KEY";

console.log(`Processing ${tweets.length} tweets for reply enrichment`);

// Collect all reply IDs first
const replyIds = [];
const tweetMap = {};

tweets.forEach(item => {
  const tweet = item.json;
  tweetMap[tweet.id] = tweet;

  if (tweet.isReply && tweet.inReplyToId) {
    replyIds.push(tweet.inReplyToId);
  }
});

console.log(`Found ${replyIds.length} replies to fetch`);

// BATCH FETCH: Get up to 100 tweets per API call
const BATCH_SIZE = 100;
const originalTweets = {};

for (let i = 0; i < replyIds.length; i += BATCH_SIZE) {
  const batch = replyIds.slice(i, i + BATCH_SIZE);
  const batchIds = batch.join(',');

  console.log(`Fetching batch ${Math.floor(i/BATCH_SIZE) + 1}: ${batch.length} tweets`);

  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.twitterapi.io/twitter/tweets?tweet_ids=${batchIds}`,
      headers: {
        'X-API-Key': apiKey,
        'Accept': 'application/json'
      },
      json: true
    });

    // Store fetched tweets by ID
    if (response.tweets) {
      response.tweets.forEach(t => {
        originalTweets[t.id] = t;
      });
    }

    console.log(`✅ Fetched ${response.tweets?.length || 0} original tweets`);

    // Rate limit: wait 1 second between batches
    if (i + BATCH_SIZE < replyIds.length) {
      await new Promise(resolve => setTimeout(resolve, 1000));
    }

  } catch (error) {
    console.log(`⚠️ Batch fetch failed: ${error.message}`);
  }
}

// Now enrich all tweets
const enrichedTweets = tweets.map(item => {
  const tweet = item.json;

  if (tweet.isReply && tweet.inReplyToId) {
    const originalTweet = originalTweets[tweet.inReplyToId];

    if (originalTweet) {
      return {
        json: {
          ...tweet,
          original_tweet_id: originalTweet.id,
          original_author_username: originalTweet.author?.userName || '',
          original_tweet_url: originalTweet.url || originalTweet.twitterUrl,
          original_full_text: originalTweet.text || ''
        }
      };
    } else {
      return {
        json: {
          ...tweet,
          original_tweet_id: tweet.inReplyToId,
          original_author_username: tweet.inReplyToUsername,
          original_tweet_url: `https://twitter.com/${tweet.inReplyToUsername}/status/${tweet.inReplyToId}`,
          original_full_text: '(Original tweet not found)'
        }
      };
    }
  }

  // Not a reply
  return {
    json: {
      ...tweet,
      original_tweet_id: '',
      original_author_username: '',
      original_tweet_url: '',
      original_full_text: ''
    }
  };
});

console.log(`✅ Enriched ${enrichedTweets.length} tweets`);
return enrichedTweets;

const tweets = $input.all();

console.log(`Formatting ${tweets.length} tweets for Google Sheets`);

return tweets.map(item => {
  const tweet = item.json;

  // Extract media URLs
  const mediaUrls = [];
  if (tweet.extendedEntities?.media) {
    tweet.extendedEntities.media.forEach(m => {
      if (m.mediaurlhttps || m.media_url_https) {
        mediaUrls.push(m.mediaurlhttps || m.media_url_https);
      }
    });
  }

  // Safe extraction
  const authorUsername = tweet.author?.userName || tweet.userName || 'unknown';

  // Construct Drive folder URL (if media exists)
  const driveFolderUrl = mediaUrls.length > 0 
    ? 'https://drive.google.com/drive/folders/YOUR_FOLDER_ID' 
    : '';

  return {
    json: {
      tweet_id: tweet.id,
      created_at: tweet.createdAt,
      author_username: authorUsername,
      tweet_url: tweet.url || tweet.twitterUrl,
      full_text: tweet.text,
      is_reply: tweet.isReply ? 'TRUE' : 'FALSE',
      reply_to_tweet_id: tweet.inReplyToId || '',
      reply_to_username: tweet.inReplyToUsername || '',
      original_tweet_id: tweet.original_tweet_id || '',
      original_author_username: tweet.original_author_username || '',
      original_tweet_url: tweet.original_tweet_url || '',
      original_full_text: tweet.original_full_text || '',
      // NEW: Quote tweet fields
      is_quote: tweet.quoted_tweet_id ? 'TRUE' : 'FALSE',
      quoted_tweet_id: tweet.quoted_tweet_id || '',
      quoted_author_username: tweet.quoted_author_username || '',
      quoted_tweet_url: tweet.quoted_tweet_url || '',
      quoted_full_text: tweet.quoted_full_text || '',
      media_urls: mediaUrls.join(', '),
      drive_folder_url: driveFolderUrl
    }
  };
});

const tweets = $input.all();

console.log(`Processing ${tweets.length} tweets with media`);

// Process each tweet
const allMediaItems = [];

tweets.forEach(item => {
  const tweetData = item.json;
  const mediaUrls = tweetData.media_urls;

  // If no media, skip
  if (!mediaUrls || mediaUrls.trim() === '') {
    console.log(`⚠️ No media URLs for tweet ${tweetData.tweet_id}`);
    return;
  }

  // Split comma-separated URLs into array
  const urlArray = mediaUrls.split(',').map(url => url.trim()).filter(url => url);

  console.log(`📸 Found ${urlArray.length} media files for tweet ${tweetData.tweet_id}`);

  // Create one item per media URL
  urlArray.forEach((url, index) => {
    // Determine file extension from URL
    let extension = '.jpg';
    if (url.includes('.mp4')) extension = '.mp4';
    if (url.includes('.png')) extension = '.png';
    if (url.includes('.gif')) extension = '.gif';

    allMediaItems.push({
      json: {
        ...tweetData,
        media_url: url,
        media_index: index + 1,
        filename: `${tweetData.author_username}_${tweetData.tweet_id}_${index + 1}${extension}`
      }
    });
  });
});

console.log(`✅ Total media items to download: ${allMediaItems.length}`);

return allMediaItems;

// Get data from both nodes
const uploadedFiles = $input.all(); // From Google Drive Upload
const downloadedFiles = $('Download Media File').all(); // From Download Media File node

console.log(`Processing ${uploadedFiles.length} uploaded files`);

// Create a map of index -> tweet data from Download Media File
const tweetDataMap = {};
downloadedFiles.forEach((item, index) => {
  tweetDataMap[index] = item.json;
});

// Group by tweet_id
const grouped = {};

uploadedFiles.forEach((item, index) => {
  const driveFileId = item.json.id; // Google Drive file ID
  const driveUrl = `https://drive.google.com/file/d/${driveFileId}/view`;

  // Get the original tweet data from Download Media File node
  const tweetData = tweetDataMap[index];

  if (!tweetData) {
    console.log(`⚠️ No tweet data found for index ${index}`);
    return;
  }

  const tweetId = tweetData.tweet_id;

  if (!grouped[tweetId]) {
    grouped[tweetId] = {
      tweet_id: tweetData.tweet_id,
      created_at: tweetData.created_at,
      author_username: tweetData.author_username,
      tweet_url: tweetData.tweet_url,
      full_text: tweetData.full_text,
      is_reply: tweetData.is_reply,
      reply_to_tweet_id: tweetData.reply_to_tweet_id || '',
      reply_to_username: tweetData.reply_to_username || '',
      original_tweet_id: tweetData.original_tweet_id || '',
      original_author_username: tweetData.original_author_username || '',
      original_tweet_url: tweetData.original_tweet_url || '',
      original_full_text: tweetData.original_full_text || '',
      // NEW: Quote tweet fields
      is_quote: tweetData.is_quote || 'FALSE',
      quoted_tweet_id: tweetData.quoted_tweet_id || '',
      quoted_author_username: tweetData.quoted_author_username || '',
      quoted_tweet_url: tweetData.quoted_tweet_url || '',
      quoted_full_text: tweetData.quoted_full_text || '',
      media_urls: tweetData.media_urls,
      drive_file_paths: []
    };
  }

  grouped[tweetId].drive_file_paths.push(driveUrl);
});

// Return one item per tweet with all drive paths joined
const result = Object.values(grouped).map(tweet => ({
  json: {
    ...tweet,
    drive_file_paths: tweet.drive_file_paths.join(', ')
  }
}));

console.log(`✅ Grouped into ${result.length} tweets with Drive paths`);
console.log(`Sample:`, JSON.stringify(result[0], null, 2));

return result;

const items = $input.all();

const results = [];

for (const item of items) {
  const url = item.json.media_url;

  if (!url) {
    console.log('⚠️ No media_url found, skipping item');
    continue;
  }

  try {
    console.log(`Downloading: ${url}`);

    // Download the file
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: url,
      returnFullResponse: true,
      encoding: 'arraybuffer'
    });

    // Determine mime type from response or URL
    let mimeType = response.headers['content-type'] || 'image/jpeg';

    // response.body is already a Buffer when encoding is 'arraybuffer'
    const binaryData = Buffer.isBuffer(response.body) 
      ? response.body 
      : Buffer.from(response.body);

    results.push({
      json: {
        // Keep ALL original tweet data (with underscores)
        ...item.json
      },
      binary: {
        data: {
          data: binaryData.toString('base64'),
          mimeType: mimeType,
          fileName: item.json.filename,
          fileExtension: item.json.filename.split('.').pop()
        }
      }
    });

    console.log(`✅ Downloaded: ${item.json.filename} (${mimeType})`);
  } catch (error) {
    console.log(`❌ Failed to download ${url}: ${error.message}`);
    // Still add the item so workflow can continue
    results.push({
      json: {
        ...item.json,
        download_error: error.message
      }
    });
  }
}

console.log(`Total files processed: ${results.length}`);

return results;

const tweets = $input.all();

console.log(`Processing ${tweets.length} tweets for quote enrichment`);

// Enrich all tweets - check if quoted_tweet data already exists
const enrichedTweets = tweets.map(item => {
  const tweet = item.json;

  // Check if this tweet has a quoted tweet
  if (tweet.quoted_tweet && tweet.quoted_tweet.id) {
    const quotedTweet = tweet.quoted_tweet;

    return {
      json: {
        ...tweet,
        quoted_tweet_id: quotedTweet.id,
        quoted_author_username: quotedTweet.author?.userName || '',
        quoted_tweet_url: quotedTweet.url || quotedTweet.twitterUrl || `https://x.com/${quotedTweet.author?.userName}/status/${quotedTweet.id}`,
        quoted_full_text: quotedTweet.text || ''
      }
    };
  }

  // Not a quote tweet
  return {
    json: {
      ...tweet,
      quoted_tweet_id: '',
      quoted_author_username: '',
      quoted_tweet_url: '',
      quoted_full_text: ''
    }
  };
});

console.log(`✅ Enriched ${enrichedTweets.length} tweets with quote data`);
return enrichedTweets;

